def get_main_shapes(grid):
    """Extract main body shapes (everything not in first 3 rows)"""
    height = len(grid)
    if height < 3:
        return {}
    body = grid[3:]

    # For each color, extract its main shape cells
    shapes = {}
    values = set()
    for row in body:
        for val in row:
            if val != 0:
                values.add(val)

    for val in values:
        cells = [(r+3, c) for r in range(len(body)) for c in range(len(body[0])) if body[r][c] == val]
        shapes[val] = cells

