import json

def create_hollow_rectangle(height, width):
    """Create a hollow rectangle pattern with specific cell positions"""
    # Based on observed patterns:
    # Demo 2 (3x6): corners at (0,0),(0,w-1),(h/2,0),(h/2,w-1); full middle; inner segment at bottom
    # This is hard to generalize

    # Let me try a different approach - look at the center column
    pattern = []
    half_h = height // 2

    for r in range(height):
        row = []
        for c in range(width):
            # Calculate expected position based on various heuristics
            if r == 0:
                # Top row: corners only for small shapes, partial fill for large
                if height <= 3:
                    row.append(1 if c in [0, width-1] else 0)
                else:
                    row.append(1 if (c >= (width-4)//2 and c < (width)//2 + (width%2)) else 0)
            elif r == half_h:
                # Middle row: always full?
                row.append(1)
            elif r == height - 1:
                # Bottom row
                if height <= 3:
                    row.append(1 if (c >= width//2-1 and c < width//2+2) else 0)
                else:
                    row.append(1 if c in [1, width-2] or (c >= 2 and c < width-2) else 0)
            else:
                # Inner rows
                if height <= 3:
                    row.append(1 if c in [0, width-1] else 0)
                else:
                    row.append(1 if c in [0, width-1] else 0)
        pattern.append(row)

    return pattern

